mapper.select:
select s.shift_id, s.store_id, s.shift_date, s.shift_code, s.shift_name, s.user_id,
       s.user_name, s.nick_name, s.open_amount, s.close_amount, s.order_count,
       s.total_amount, s.settle_id, s.status, s.open_time, s.close_time,
       s.create_time, s.update_time
from biz_cashier_shift s


        and s.shift_date = #{shiftDate}


        and s.shift_code = #{shiftCode}


        and s.shift_name = #{shiftName}


        and s.user_id = #{userId}


        and s.user_name = #{userName}


        and s.status = #{status}


        and s.shift_date >= #{params.beginTime}


        and s.shift_date <= #{params.endTime}


order by s.shift_id desc
